blocks.crop_admission:
def _crop_pools(v, seeds_left, day):
    free = [q for q in sorted(v["empty"], key=lambda q: (_shed_dist(q), q)) if q not in S["claimed_sites"]]
    n_rec = seeds_left.get("STRAWBERRY", 0) + seeds_left.get("TOMATO", 0)
    n_one = sum(seeds_left.get(c, 0) for c in CROP_SPECS) - n_rec
    if n_one < 0:
        n_one = 0
    near = [q for q in free if _shed_dist(q) <= NEAR_RADIUS]
    far_left = [q for q in free if _shed_dist(q) > NEAR_RADIUS]
    rec_sites = near[:n_rec]
    near_left = near[n_rec:]
    if len(rec_sites) < n_rec:
        take = n_rec - len(rec_sites)
        rec_sites = rec_sites + far_left[:take]
        far_left = far_left[take:]
    one_sites = far_left[:n_one]
    if len(one_sites) < n_one:
        one_sites = one_sites + near_left[:n_one - len(one_sites)]
    plant = rec_sites + one_sites
    return {"urgent": list(v["urgent"]), "wwater": list(v["wwater"]), "harvest": list(v["harvest"]), "water": list(v["water"]),
            "fert": list(v["fert"]), "plant": plant, "weeds": list(v["weeds"]), "slack": list(v["slack"])}


def _plant_choice(pos, seeds_left):
    d = _shed_dist(pos)
    if d <= NEAR_RADIUS:
        order = ["STRAWBERRY", "TOMATO", "MELON", "CARROT", "WHEAT"]
    elif d <= NEAR_RADIUS + 3:
        order = ["MELON", "CARROT", "WHEAT", "STRAWBERRY", "TOMATO"]
    else:
        order = ["WHEAT", "MELON", "CARROT", "TOMATO", "STRAWBERRY"]
    for c in order:
        if seeds_left.get(c, 0) > 0:
            return c
    return None


def _task_valid(tp, kind, v, day, hour, carry, seeds_left):
    t = v["tiles"][tp[1]][tp[0]]
    if kind in ("urgent", "water", "slack", "wwater"):
        return isinstance(t, dict) and t.get("kind") == "PLANT" and not t.get("watered_today")
    if kind == "harvest":
        return isinstance(t, dict) and t.get("kind") == "PLANT" and t.get("yield_units", 0) > 0
    if kind == "fert":
        return carry.get("FERTILIZER", 0) > 0 and isinstance(t, dict) and _fert_eligible(t, day)
    if kind == "plant":
        return t is None and _plant_choice(tp, seeds_left) is not None and hour < 22
    if kind == "weeds":
        return isinstance(t, dict) and t.get("kind") == "WEED"
    return False

blocks.sweep:
def _build_sweep(i, pos, v, day, hour, carry, pools, seeds_left):
    tiers = ["urgent", "wwater", "harvest", "water"]
    if carry.get("FERTILIZER", 0) > 0:
        tiers = ["urgent", "fert", "wwater", "harvest", "water"]
    # B: days 10-12, put ripe high-yield MELON harvests ahead of watering so they carry
    # into the day-10 price window instead of sitting a day.
    if 10 <= day <= 12:
        big_melon = [tp for tp in pools["harvest"]
                     if v["tiles"][tp[1]][tp[0]].get("kind") == "PLANT"
                     and v["tiles"][tp[1]][tp[0]].get("crop") == "MELON"
                     and v["tiles"][tp[1]][tp[0]].get("yield_units", 0) >= 5]
        if big_melon:
            tiers = ["urgent", "harvest", "wwater", "water"]
            if carry.get("FERTILIZER", 0) > 0:
                tiers = ["urgent", "fert", "harvest", "wwater", "water"]
    if hour < 22:
        tiers.append("plant")
    tiers.append("weeds")
    if hour >= 14:
        tiers.append("slack")
    first = None
    for kind in tiers:
        if pools[kind]:
            tp = _nearest(pos, pools[kind])
            first = (tp, kind)
            pools[kind].remove(tp)
            break
    if first is None:
        return None
    sweep = [first]
    cur = first[0]
    if first[1] == "urgent" and pools["urgent"]:
        tiers = ["urgent", "harvest"]
    while len(sweep) < CROP_SWEEP_LEN:
        best = None
        for kind in tiers:
            for tp in pools[kind]:
                d = _dist(cur, tp)
                if d <= CROP_SWEEP_RADIUS and (best is None or d < best[0]):
                    best = (d, tp, kind)
        if best is None:
            break
        _d, tp, kind = best
        pools[kind].remove(tp)
        sweep.append((tp, kind))
        cur = tp
    return sweep


def _crop_step(i, pos, v, day, hour, carry, pools, seeds_left):
    sweep = S["sweep"].get(i)
    if not sweep:
        sweep = _build_sweep(i, pos, v, day, hour, carry, pools, seeds_left)
        if not sweep:
            S["sweep"].pop(i, None)
            return None
        S["sweep"][i] = sweep
    while sweep:
        tp, kind = sweep[0]
        if not _task_valid(tp, kind, v, day, hour, carry, seeds_left):
            sweep.pop(0)
            continue
        if pos != tp:
            return [_step(pos, tp)]
        sweep.pop(0)
        if kind in ("urgent", "water", "slack", "wwater"):
            return ["WATER"]
        if kind == "harvest":
            return ["HARVEST"]
        if kind == "fert":
            return ["FERTILIZE"]
        if kind == "weeds":
            return ["DIG"]
        if kind == "plant":
            c = _plant_choice(tp, seeds_left)
            seeds_left[c] -= 1
            sweep.insert(0, (tp, "urgent"))
            return ["PLANT", c]
    S["sweep"].pop(i, None)
    if any(pools[k] for k in pools):
        return _crop_step(i, pos, v, day, hour, carry, pools, seeds_left)
    remaining = 23 - hour
    best = None
    for j, sw in list(S["sweep"].items()):
        if j == i or not sw:
            continue
        eta = 0
        cur = v["positions"][j]
        for idx, (tp, kind) in enumerate(sw):
            eta += _dist(cur, tp) + 1
            cur = tp
            if kind == "urgent" and eta > remaining:
                mine = _dist(pos, tp) + 1
                if mine <= remaining and (best is None or mine < best[0]):
                    best = (mine, j, idx)
    if best is not None:
        _m, j, idx = best
        tp, kind = S["sweep"][j].pop(idx)
        S["sweep"][i] = [(tp, kind)]
        return _crop_step(i, pos, v, day, hour, carry, pools, seeds_left)
    best = None
    for j, sw in S["sweep"].items():
        if j == i or len(sw) < 2:
            continue
        for idx in range(len(sw) - 1, 0, -1):
            if sw[idx][1] == "urgent" and (best is None or len(sw) > len(S["sweep"][best[0]])):
                best = (j, idx)
                break
    if best is None:
        for j, sw in S["sweep"].items():
            if j != i and len(sw) >= 3 and (best is None or len(sw) > len(S["sweep"][best[0]])):
                best = (j, len(sw) - 1)
    if best is not None:
        j, idx = best
        task = S["sweep"][j].pop(idx)
        S["sweep"][i] = [task]
        return _crop_step(i, pos, v, day, hour, carry, pools, seeds_left)
    return None
